import{_ as t,c as p,o as e,a3 as r}from"./chunks/framework.CoV49S2T.js";const A=JSON.parse('{"title":"よくある質問（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/faq.md","filePath":"ja/guide/faq.md","lastUpdated":1786597585000}'),o={name:"ja/guide/faq.md"};function n(s,a,i,l,c,g){return e(),p("div",null,[...a[0]||(a[0]=[r('<h1 id="よくある質問-faq" tabindex="-1">よくある質問（FAQ） <a class="header-anchor" href="#よくある質問-faq" aria-label="Permalink to &quot;よくある質問（FAQ）&quot;">​</a></h1><p><strong>Q: ClipboardxAI とは何ですか？</strong></p><p>A: ClipboardxAI は macOS 向けのスマートなクリップボードマネージャーです。コピーしたものすべての検索可能な履歴を保持し、その上でアクションを実行できます — 要約、翻訳、テキストの整理、あるいはクラウドの AI モデルへの送信です。</p><p><strong>Q: どの macOS バージョンに対応していますか？</strong></p><p>A: macOS 14 Sonoma 以降で、Apple Silicon（M シリーズ）向けに最適化され、Intel にも対応しています。</p><p><strong>Q: どうやってインストールしますか？</strong></p><p>A: <a href="/ja/">Mac App Store</a>（推奨）からダウンロードするか、<a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a> から最新のビルドを取得してください。<a href="/ja/guide/installation.html">インストールガイド</a>を参照してください。</p><p><strong>Q: ClipboardxAI は無料ですか？</strong></p><p>A: ClipboardxAI は Mac App Store で提供される有料アプリです。購入後は内蔵のローカルツールがすべて含まれ、アカウントは不要です。クラウド AI アクションは <em>ご自身の</em> プロバイダーの API key を使用するため、お支払いは AI プロバイダーへ直接となり、アプリ内での追加課金はありません。</p><p><strong>Q: どの AI プロバイダーに対応していますか？</strong></p><p>A: 任意の OpenAI 互換プロバイダー: DeepSeek、MiniMax、Zhipu GLM、Kimi (Moonshot)、Mistral、およびローカルの Ollama — さらに OpenAI、Anthropic、Gemini にも対応しています。キーは Keychain に保存されます。</p><p><strong>Q: オフラインで動作しますか？</strong></p><p>A: はい。クリップボード履歴と内蔵のローカルツール（リンク抽出、集計、空白行削除など）は、インターネット接続なしで Mac 上のみで完全に動作します。</p><p><strong>Q: クリップボードデータはプライベートですか？</strong></p><p>A: 履歴はお使いのデバイスに留まります。クラウド AI はオプトインであり、コンテンツは自分で設定したプロバイダーにのみ、Keychain のキーを使って送信されます。私たちがクリップを受信したり保存したりすることは一切なく、テレメトリも存在しません。<a href="/ja/guide/privacy.html">プライバシーポリシー</a>を参照してください。</p><p><strong>Q: アクションを増やすにはどうすればよいですか？</strong></p><p>A: <a href="/ja/marketplace/">Marketplace</a> を閲覧し、任意のアクションの <strong>Install</strong> をクリックしてください。ディープリンクを通じてアプリが開き、<strong>Installed（インストール済み）</strong> 一覧に表示されます。</p><p><strong>Q: アプリをアップデートするには？</strong></p><p>A: Mac App Store 版は自動的に更新されます。GitHub ビルドの場合は、最新のリリースをダウンロードし、<code>Applications</code> 内のアプリを置き換えてください。</p><p><strong>Q: バグを報告したり機能をリクエストしたりするには？</strong></p><p>A: <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub リポジトリ</a>で issue を作成してください。macOS のバージョン、アプリのバージョン、再現手順を含めてください。</p><p><strong>Q: データはどこに保存されますか？</strong></p><p>A: サンドボックスのコンテナ内に保存されます：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.clipboard/Data/Library/Application Support/com.w3cub.clipboard/</span></span></code></pre></div><p>API key はシステムの Keychain にあり、そのフォルダーには含まれません。</p>',25)])])}const h=t(o,[["render",n]]);export{A as __pageData,h as default};
